mapper.select:
SELECT * FROM (select A.TDY_UNIT_VALUE as tdyUnitValue, A.TDY_UNIT_VALUE_SUM as tdyUnitValueSum, A.CDATE AS cdate, A.YIELD_7 AS yield7, A.TDY_SHARE_AMT AS tdyShareAmt, B.PORTFOLIO_ID as portfolioId, B.PORTFOLIO_NAME as portfolioName FROM BOK_POSITION_PRD A JOIN PTL_PORTFOLIO B ON B.PORTFOLIO_ID=A.FINPROD_ID
and B.PORTFOLIO_ID =#{portfolioId}
and A.CDATE>=STR_TO_DATE(#{startDate},'%Y-%m-%d')
and STR_TO_DATE(#{endDate},'%Y-%m-%d')>=A.CDATE
)

SELECT C.* ,A.effDate ,A.PORTFOLIO_ID ,D.PORTFOLIO_NAME ,B.EVAL_INDEX FROM (SELECT PTL_STGY_ID ,PORTFOLIO_ID ,STRATEGY_ID ,max(EFF_DATE) AS effDate FROM PTL_PORTFOLIO_STGY WHERE #{endDate}>=IF(!ISNULL(DATE_FORMAT(EFF_DATE,'%Y-%m-%d')),DATE_FORMAT(EFF_DATE,'%Y-%m-%d'),'0') AND PORTFOLIO_ID=#{portfolioId} GROUP BY PORTFOLIO_ID,PTL_STGY_ID,STRATEGY_ID) A JOIN PTL_PORTFOLIO_EVAL B ON A.PTL_STGY_ID=B.PTL_STGY_ID
JOIN PTL_INCOME_INDEX C ON B.INDEX_ID=C.INDEX_ID JOIN PTL_PORTFOLIO D ON A.PORTFOLIO_ID=D.PORTFOLIO_ID
and A.STRATEGY_ID =#{strategyId}
